interface.definition:
a!localVariables(
  local!fechaDesde: userdatetime(year(now()), 1, 1, 0, 0, 0),
  local!fechaHasta: now(),
  local!Anio: year(now()),
  local!QueryCorreos: #"SYSTEM_SYSRULES_queryEntity_v2"(
    entity: #"_a-0000ef02-3502-8000-9bf1-011c48011c48_1557667",
    query: #"SYSTEM_SYSRULES_query"(
      selection: #"SYSTEM_SYSRULES_querySelection"(
        columns: {
          #"SYSTEM_SYSRULES_queryColumn"(field: "APP_MAIL_POLLER_ID")
        }
      ),
      logicalExpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
        operator: "AND",
        filters: {
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "SYS_DATE",
            operator: ">=",
            value: local!fechaDesde
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "SYS_DATE",
            operator: "<=",
            value: local!fechaHasta
          )
        },
        ignoreFiltersWithEmptyValues: true
      ),
      pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: - 1)
    ),
    fetchTotalCount: true
  ),
  local!TotalCorreos: local!QueryCorreos.totalCount,
  local!UltimaSincronizacion: index(
    #"SYSTEM_SYSRULES_queryEntity_v2"(
      entity: #"_a-0000ef02-3502-8000-9bf1-011c48011c48_1557667",
      query: #"SYSTEM_SYSRULES_query"(
        logicalExpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
          operator: "AND",
          filters: {},
          ignoreFiltersWithEmptyValues: true
        ),
        pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
          startIndex: 1,
          batchSize: 1,
          sort: #"SYSTEM_SYSRULES_sortInfo"(field: "SYS_DATE", ascending: false)
        )
      ),
      fetchTotalCount: true
    ),
    "data",
    "SYS_DATE",
    1,
    null
  ),
  local!TotalCorreosGestorDocumental: #"SYSTEM_SYSRULES_queryEntity_v2"(
    entity: #"_a-0000ef02-3502-8000-9bf1-011c48011c48_1557667",
    query: #"SYSTEM_SYSRULES_query"(
      selection: #"SYSTEM_SYSRULES_querySelection"(
        columns: {
          #"SYSTEM_SYSRULES_queryColumn"(field: "APP_MAIL_POLLER_ID")
        }
      ),
      logicalExpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
        operator: "AND",
        filters: {
          #"SYSTEM_SYSRULES_queryFilter"(field: "SYNC", operator: "=", value: true),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "SYS_DATE",
            operator: ">=",
            value: local!fechaDesde
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "SYS_DATE",
            operator: "<=",
            value: local!fechaHasta
          )
        },
        ignoreFiltersWithEmptyValues: true
      ),
      pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 1)
    ),
    fetchTotalCount: true
  ).totalCount,
  local!TotalCorreosClasificados: #"SYSTEM_SYSRULES_queryEntity_v2"(
    entity: #"_a-0000ef02-3502-8000-9bf1-011c48011c48_1557667",
    query: #"SYSTEM_SYSRULES_query"(
      selection: #"SYSTEM_SYSRULES_querySelection"(
        columns: {
          #"SYSTEM_SYSRULES_queryColumn"(field: "APP_MAIL_POLLER_ID")
        }
      ),
      logicalExpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
        operator: "AND",
        filters: {
          #"SYSTEM_SYSRULES_queryFilter"(field: "ESTADO", operator: "=", value: 2),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "SYS_DATE",
            operator: ">=",
            value: local!fechaDesde
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "SYS_DATE",
            operator: "<=",
            value: local!fechaHasta
          )
        },
        ignoreFiltersWithEmptyValues: true
      ),
      pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 1)
    ),
    fetchTotalCount: true
  ).totalCount,
  local!remitentes: #"SYSTEM_SYSRULES_queryRecordType_v4"(
    recordType: #"urn:appian:record-type:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4",
    fields: #"SYSTEM_SYSRULES_aggregationFields"(
      groupings: {
        #"SYSTEM_SYSRULES_grouping"(
          field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/a3c256a0-ded5-4f3d-9686-fefe4e4057b0",
          alias: "FROM_EMAIL"
        )
      },
      measures: {
        #"SYSTEM_SYSRULES_measure"(
          field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/9aa2ba60-e02c-4792-aa94-797e7da3ca0c",
          function: "DISTINCT_COUNT",
          alias: "COUNT"
        )
      }
    ),
    filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
      operator: "AND",
      filters: {
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/04a88c29-aa44-49a7-8e06-a3cf2e0e2c01",
          operator: ">=",
          value: local!fechaDesde
        ),
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:a7d6704d-9993-4c22-8a68-56da794e8cb4/04a88c29-aa44-49a7-8e06-a3cf2e0e2c01",
          operator: "<=",
          value: local!fechaHasta
        )
      },
      ignoreFiltersWithEmptyValues: true
    ),
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
      startIndex: 1,
      batchSize: 10,
      sort: { #"SYSTEM_SYSRULES_sortInfo"(field: "COUNT") }
    ),
    fetchTotalCount: true()
  ).data,
  local!AITokens: #"SYSTEM_SYSRULES_queryRecordType_v4"(
    recordType: #"urn:appian:record-type:v1:1b94f213-04a2-4dc5-9852-ed822750fc29",
    fields: #"SYSTEM_SYSRULES_aggregationFields"(
      measures: {
        #"SYSTEM_SYSRULES_measure"(
          field: #"urn:appian:record-field:v1:1b94f213-04a2-4dc5-9852-ed822750fc29/761d1e22-31ee-4392-b5d4-6d4781881603",
          function: "SUM",
          alias: "inputtokens"
        ),
        #"SYSTEM_SYSRULES_measure"(
          field: #"urn:appian:record-field:v1:1b94f213-04a2-4dc5-9852-ed822750fc29/b549a74a-ff35-4301-be46-6946e4186030",
          function: "SUM",
          alias: "outputtokens"
        )
      }
    ),
    filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
      operator: "AND",
      filters: {
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:1b94f213-04a2-4dc5-9852-ed822750fc29/8607fecd-f5f9-4eba-b54d-b496c9ccfdd9",
          operator: ">=",
          value: local!fechaDesde
        ),
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:1b94f213-04a2-4dc5-9852-ed822750fc29/8607fecd-f5f9-4eba-b54d-b496c9ccfdd9",
          operator: "<=",
          value: local!fechaHasta
        )
      },
      ignoreFiltersWithEmptyValues: true
    ),
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 100)
  ).data,
  /* ── Datos de etiquetas para la tabla ── */
  local!etiquetasData: #"SYSTEM_SYSRULES_queryRecordType_v4"(
    recordType: #"urn:appian:record-type:v1:76845980-0d36-4ec8-b5d3-b0700159ddfd",
    fields: #"SYSTEM_SYSRULES_aggregationFields"(
      groupings: {
        #"SYSTEM_SYSRULES_grouping"(
          field: #"urn:appian:record-field:v1:76845980-0d36-4ec8-b5d3-b0700159ddfd/2081b480-c047-45f8-bdd5-c823d085570b/c328359a-a4b1-488a-8324-7beafa21d9ae",
          alias: "Etiqueta"
        ),
        #"SYSTEM_SYSRULES_grouping"(
          field: #"urn:appian:record-field:v1:76845980-0d36-4ec8-b5d3-b0700159ddfd/2081b480-c047-45f8-bdd5-c823d085570b/8a5a5844-84da-4c47-a007-3d4c7cedaf35",
          alias: "Color"
        )
      },
      measures: {
        #"SYSTEM_SYSRULES_measure"(
          field: #"urn:appian:record-field:v1:76845980-0d36-4ec8-b5d3-b0700159ddfd/92253a1e-b309-4041-bfae-d5aa13d74756",
          function: "DISTINCT_COUNT",
          alias: "Cuenta"
        )
      }
    ),
    filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
      operator: "AND",
      filters: {
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:76845980-0d36-4ec8-b5d3-b0700159ddfd/6459fe0c-816e-4666-a512-6d5bcfbaa191",
          operator: "in",
          value: cast(
            101,
            index(
              local!QueryCorreos,
              "data",
              "APP_MAIL_POLLER_ID",
              0
            )
          )
        )
      },
      ignoreFiltersWithEmptyValues: true
    ),
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
      startIndex: 1,
      batchSize: 100,
      sort: {
        #"SYSTEM_SYSRULES_sortInfo"(field: "Cuenta", ascending: false)
      }
    ),
    fetchTotalCount: true()
  ).data,
  /* Máximo para calcular el ancho de la barra visual */
  local!maxEtiqueta: if(
    a!isNullOrEmpty(local!etiquetasData),
    1,
    reduce(
      fn!max,
      0,
      index(local!etiquetasData, "Cuenta", {})
    )
  ),
  /* ── Query: correos con etiqueta CORREO_NO_CLARO (id=49) ── */
  local!totalCorreosNoClaro: #"SYSTEM_SYSRULES_queryEntity_v2"(
    entity: #"_a-0000ef02-3502-8000-9bf1-011c48011c48_1557667",
    query: #"SYSTEM_SYSRULES_query"(
      selection: #"SYSTEM_SYSRULES_querySelection"(
        columns: {
          #"SYSTEM_SYSRULES_queryColumn"(field: "APP_MAIL_POLLER_ID")
        }
      ),
      logicalExpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
        operator: "AND",
        filters: {
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "SYS_DATE",
            operator: ">=",
            value: local!fechaDesde
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "SYS_DATE",
            operator: "<=",
            value: local!fechaHasta
          )
        },
        ignoreFiltersWithEmptyValues: true
      ),
      pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: - 1)
    ),
    fetchTotalCount: true
  ),
  local!correoNoClaroCount: #"SYSTEM_SYSRULES_queryRecordType_v4"(
    recordType: #"urn:appian:record-type:v1:76845980-0d36-4ec8-b5d3-b0700159ddfd",
    fields: #"SYSTEM_SYSRULES_aggregationFields"(
      measures: {
        #"SYSTEM_SYSRULES_measure"(
          field: #"urn:appian:record-field:v1:76845980-0d36-4ec8-b5d3-b0700159ddfd/92253a1e-b309-4041-bfae-d5aa13d74756",
          function: "DISTINCT_COUNT",
          alias: "Cuenta"
        )
      }
    ),
    filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
      operator: "AND",
      filters: {
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:76845980-0d36-4ec8-b5d3-b0700159ddfd/b166a748-4a36-43a3-99a4-412a24157620",
          operator: "=",
          value: 49
        ),
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:76845980-0d36-4ec8-b5d3-b0700159ddfd/6459fe0c-816e-4666-a512-6d5bcfbaa191",
          operator: "in",
          value: cast(
            101,
            index(
              local!totalCorreosNoClaro,
              "data",
              "APP_MAIL_POLLER_ID",
              0
            )
          )
        )
      },
      ignoreFiltersWithEmptyValues: true
    ),
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 1)
  ).data[1]["Cuenta"],
  /* ── Notificaciones con datos reales ── */
  local!pendientesClasificacion: local!TotalCorreos - local!TotalCorreosClasificados,
  local!notificaciones: {
    a!map(
      icono: "exclamation-triangle",
      color: "#F57F17",
      mensaje: local!pendientesClasificacion & " correos pendientes de clasificación",
      detalle: "Se han clasificado " & local!TotalCorreosClasificados & " de " & local!TotalCorreos & " recolectados"
    ),
    a!map(
      icono: "times-circle",
      color: "#C62828",
      mensaje: a!defaultValue(local!correoNoClaroCount, 0) & " correos con etiqueta CORREO_NO_CLARO",
      detalle: "Revisar criterios de clasificación del modelo"
    ),
    a!map(
      icono: "info-circle",
      color: "#1565C0",
      mensaje: "Última sincronización: " & if(
        a!isNullOrEmpty(local!UltimaSincronizacion),
        "Sin registros",
        datetext(local!UltimaSincronizacion, "dd/MM/yy")
      ),
      detalle: "El sistema está recolectando correos correctamente"
    )
  },
  #"SYSTEM_SYSRULES_headerContentLayout"(
    header: {
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_sideBySideLayout"(
                    items: {
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_imageField_v1"(
                          label: "Imagen",
                          labelPosition: "COLLAPSED",
                          images: {
                            #"SYSTEM_SYSRULES_documentImage"(document: #"_a-0000ef03-0467-8000-9bf2-011c48011c48_1561798")
                          },
                          size: "SMALL_PLUS",
                          style: "STANDARD",
                          isThumbnail: false
                        ),
                        width: "MINIMIZE"
                      ),
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          label: "",
                          labelPosition: "ABOVE",
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "Control operativo",
                              size: "LARGE",
                              color: "#FFFFFF",
                              style: "STRONG"
                            )
                          }
                        )
                      )
                    },
                    alignVertical: "MIDDLE"
                  )
                },
                width: "3X"
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_dateTimeField"(
                    label: "Desde",
                    labelPosition: "ADJACENT",
                    value: local!fechaDesde,
                    saveInto: local!fechaDesde
                  ),
                  #"SYSTEM_SYSRULES_dateTimeField"(
                    label: "Hasta",
                    labelPosition: "ADJACENT",
                    value: local!fechaHasta,
                    saveInto: local!fechaHasta
                  )
                },
                width: "1X"
              )
            },
            alignVertical: "MIDDLE",
            spacing: "STANDARD"
          )
        },
        marginBelow: "STANDARD",
        style: "#1d2d44",
        showBorder: false,
        padding: "LESS"
      )
    },
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_cardLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: { "CORREOS RECOLECTADOS" },
                        color: "SECONDARY",
                        style: { "STRONG" }
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(
                        icon: "database",
                        size: "EXTRA_LARGE",
                        color: "#1565C0"
                      ),
                      char(9),
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: { local!TotalCorreos },
                        size: "EXTRA_LARGE",
                        color: "#1565C0"
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: "Última recolección: ",
                        color: "SECONDARY",
                        style: "STRONG"
                      ),
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: {
                          if(
                            a!isNullOrEmpty(local!UltimaSincronizacion),
                            "Sin registros",
                            datetext(local!UltimaSincronizacion, "dd/MM/yy")
                          )
                        },
                        color: "SECONDARY"
                      )
                    },
                    align: "RIGHT"
                  )
                },
                height: "MEDIUM",
                shape: "ROUNDED"
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_cardLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: { "CORREOS CLASIFICADOS" },
                        color: "SECONDARY",
                        style: { "STRONG" }
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(
                        icon: "file-import",
                        size: "EXTRA_LARGE",
                        color: "#2E7D32"
                      ),
                      char(9),
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: { local!TotalCorreosClasificados },
                        size: "EXTRA_LARGE",
                        color: "#2E7D32"
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: "Pendientes: ",
                        color: "SECONDARY",
                        style: "STRONG"
                      ),
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: {
                          local!TotalCorreos - local!TotalCorreosGestorDocumental
                        },
                        color: "SECONDARY"
                      )
                    },
                    align: "RIGHT"
                  )
                },
                height: "MEDIUM",
                shape: "ROUNDED"
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_cardLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: {
                          "CORREOS RADICADOS EN GESTOR DOCUMENTAL"
                        },
                        color: "SECONDARY",
                        style: { "STRONG" }
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(
                        icon: "file-export",
                        size: "EXTRA_LARGE",
                        color: "#999999"
                      ),
                      char(9),
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: { local!TotalCorreosGestorDocumental },
                        size: "EXTRA_LARGE",
                        color: if(
                          local!TotalCorreos >= local!TotalCorreosGestorDocumental,
                          "POSITIVE",
                          "NEGATIVE"
                        )
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(icon: "bullseye", color: "SECONDARY"),
                      " ",
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: { local!TotalCorreosGestorDocumental },
                        color: "SECONDARY"
                      )
                    },
                    align: "RIGHT"
                  )
                },
                height: "MEDIUM",
                shape: "ROUNDED"
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_cardLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: { "TOKENS GASTADOS" },
                        color: "SECONDARY",
                        style: { "STRONG" }
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(
                        icon: "bolt",
                        size: "EXTRA_LARGE",
                        color: "#F57F17"
                      ),
                      char(9),
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: sum(
                          index(local!AITokens, "inputtokens", null),
                          index(local!AITokens, "outputtokens", null)
                        ),
                        size: "EXTRA_LARGE",
                        color: "#F57F17"
                      )
                    },
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: "Costo estimado: ",
                        color: "SECONDARY",
                        style: "STRONG"
                      ),
                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: { "$0.00" }, color: "SECONDARY")
                    },
                    align: "RIGHT"
                  )
                },
                height: "MEDIUM",
                shape: "ROUNDED"
              )
            }
          )
        }
      ),
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextIcon"(icon: "bell", color: "#1d2d44"),
              " ",
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: "Notificaciones",
                size: "MEDIUM",
                style: "STRONG",
                color: "#1d2d44"
              )
            },
            marginBelow: "LESS"
          ),
          #"SYSTEM_SYSRULES_forEach"(
            items: local!notificaciones,
            expression: #"SYSTEM_SYSRULES_cardLayout"(
              contents: {
                #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: {
                          #"SYSTEM_SYSRULES_richTextIcon"(
                            icon: fv!item.icono,
                            color: fv!item.color,
                            size: "LARGE"
                          )
                        },
                        marginAbove: "NONE",
                        marginBelow: "NONE"
                      ),
                      width: "MINIMIZE"
